import React, { useState, useRef } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [userId, setUserId] = useState("");
  const [qrData, setQrData] = useState("");
  const [photo, setPhoto] = useState("");
  const [showPayment, setShowPayment] = useState(false);
  const [utrNumber, setUtrNumber] = useState("");
  const [verifying, setVerifying] = useState(false);
  const [appOpened, setAppOpened] = useState(false);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  // ── Your UPI details ─────────────────────────────────────
  const YOUR_UPI_ID = "arunsekar664@okaxis";
  const AMOUNT = "1";
  const PAYEE_NAME = "CollegeEvent";
  // ─────────────────────────────────────────────────────────

  /* =============================
     DETECT DEVICE
  ============================= */
  const isMobile = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
  const isAndroid = /Android/i.test(navigator.userAgent);
  const isIOS = /iPhone|iPad|iPod/i.test(navigator.userAgent);

  /* =============================
     UPI PAYMENT OPENER
  ============================= */
  const openUPIApp = (app) => {
    const encodedName = encodeURIComponent(PAYEE_NAME);
    const encodedNote = encodeURIComponent("EventRegistration");

    const upiBase = `pa=${YOUR_UPI_ID}&pn=${encodedName}&am=${AMOUNT}&cu=INR&tn=${encodedNote}`;

    const links = {
      gpay: {
        android: `intent://pay?${upiBase}#Intent;scheme=tez;package=com.google.android.apps.nbu.paisa.user;end`,
        ios: `tez://upi/pay?${upiBase}`,
        web: "https://pay.google.com/",
      },
      phonepe: {
        android: `intent://pay?${upiBase}#Intent;scheme=phonepe;package=com.phonepe.app;end`,
        ios: `phonepe://pay?${upiBase}`,
        web: "https://phon.pe/",
      },
      paytm: {
        android: `intent://pay?${upiBase}#Intent;scheme=paytmmp;package=net.one97.paytm;end`,
        ios: `paytmmp://pay?${upiBase}`,
        web: "https://paytm.com/",
      },
      any: {
        android: `upi://pay?${upiBase}`,
        ios: `upi://pay?${upiBase}`,
        web: `upi://pay?${upiBase}`,
      },
    };

    const appLinks = links[app];

    if (isAndroid) {
      window.location.href = appLinks.android;
    } else if (isIOS) {
      window.location.href = appLinks.ios;
    } else {
      window.open(appLinks.web, "_blank");
    }

    setAppOpened(true);
  };

  /* =============================
     INPUT CHANGE
  ============================= */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* =============================
     SHOW PAYMENT SCREEN
  ============================= */
  const handleShowPayment = (e) => {
    e.preventDefault();
    setShowPayment(true);
  };

  /* =============================
     VERIFY UTR + REGISTER
  ============================= */
  const verifyAndRegister = async () => {
    if (!utrNumber.trim()) {
      alert("Please enter your UTR / Transaction ID");
      return;
    }
    if (utrNumber.trim().length < 10) {
      alert("UTR must be at least 10 digits. Please check and try again.");
      return;
    }

    setVerifying(true);
    try {
      const res = await axios.post("http://localhost:5000/verify-utr", {
        utrNumber: utrNumber.trim(),
        amount: AMOUNT,
        ...formData,
        photo,
      });

      if (res.data.success) {
        setUserId(res.data.userId);
        setQrData(res.data.qrData);
        alert("Payment Verified! Registration Successful.");
      } else {
        alert(res.data.message || "UTR verification failed. Please try again.");
      }
    } catch (err) {
      alert("Verification failed. Please contact support.");
    } finally {
      setVerifying(false);
    }
  };

  /* =============================
     OPEN CAMERA
  ============================= */
  const openCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      streamRef.current = stream;
      videoRef.current.srcObject = stream;
      videoRef.current.play();
    } catch {
      alert("Camera access denied");
    }
  };

  /* =============================
     CAPTURE PHOTO
  ============================= */
  const capturePhoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(video, 0, 0);
    const image = canvas.toDataURL("image/png");
    setPhoto(image);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
    }
  };

  /* =============================
     DOWNLOAD ID CARD
  ============================= */
  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "Event_ID_Card.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  /* =============================
     BUTTON STYLE
  ============================= */
  const btnBase = {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    gap: "10px",
    padding: "13px 20px",
    border: "none",
    borderRadius: "10px",
    fontSize: "15px",
    fontWeight: "bold",
    cursor: "pointer",
    width: "100%",
    boxSizing: "border-box",
    transition: "opacity 0.2s",
  };

  return (
    <div>
      <Navbar />

      <div style={{ textAlign: "center", padding: "20px" }}>
        <h2>Event Registration</h2>

        {/* ── STEP 1: FORM ── */}
        {!showPayment && !qrData && (
          <form onSubmit={handleShowPayment}>
            <input name="name" placeholder="Name" onChange={handleChange} required />
            <br /><br />
            <input name="college_name" placeholder="College Name" onChange={handleChange} required />
            <br /><br />
            <input name="phone" placeholder="Phone" onChange={handleChange} required />
            <br /><br />
            <input name="email" placeholder="Email" onChange={handleChange} required />
            <br /><br />
            <h3>Selected Event: {eventName}</h3>
            <button
              type="submit"
              style={{ ...btnBase, backgroundColor: "#4f46e5", color: "white", maxWidth: "260px", margin: "auto" }}
            >
              Proceed to Pay ₹{AMOUNT}
            </button>
          </form>
        )}

        {/* ── STEP 2: PAYMENT SCREEN ── */}
        {showPayment && !qrData && (
          <div style={{ maxWidth: "400px", margin: "auto", textAlign: "left" }}>
            <h3 style={{ textAlign: "center" }}>Pay ₹{AMOUNT} to Register</h3>

            {/* Desktop notice */}
            {!isMobile && (
              <div style={{
                backgroundColor: "#fef9c3",
                border: "1px solid #f59e0b",
                borderRadius: "8px",
                padding: "10px 14px",
                marginBottom: "16px",
                fontSize: "13px",
                color: "#78350f",
              }}>
                <strong>Using desktop?</strong> Open this page on your mobile phone to directly
                launch GPay / PhonePe / Paytm. On desktop, buttons open the website version.
                You can also scan the QR below with your phone.
              </div>
            )}

            {/* App Buttons */}
            <p style={{ fontWeight: "600", marginBottom: "8px", fontSize: "14px" }}>
              Select payment app:
            </p>
            <div style={{ display: "flex", flexDirection: "column", gap: "10px", marginBottom: "20px" }}>

              <button onClick={() => openUPIApp("gpay")} style={{ ...btnBase, backgroundColor: "#1a73e8", color: "#fff" }}>
                <img
                  src="https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Google_Pay_Logo.svg/512px-Google_Pay_Logo.svg.png"
                  alt="GPay" width="22" height="22" style={{ objectFit: "contain" }}
                />
                Pay with GPay
              </button>

              <button onClick={() => openUPIApp("phonepe")} style={{ ...btnBase, backgroundColor: "#5f259f", color: "#fff" }}>
                <img
                  src="https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/PhonePe_Logo.svg/512px-PhonePe_Logo.svg.png"
                  alt="PhonePe" width="22" height="22" style={{ objectFit: "contain" }}
                />
                Pay with PhonePe
              </button>

              <button onClick={() => openUPIApp("paytm")} style={{ ...btnBase, backgroundColor: "#00BAF2", color: "#fff" }}>
                <img
                  src="https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Paytm_Logo_%28standalone%29.svg/512px-Paytm_Logo_%28standalone%29.svg.png"
                  alt="Paytm" width="22" height="22" style={{ objectFit: "contain" }}
                />
                Pay with Paytm
              </button>

              <button onClick={() => openUPIApp("any")} style={{ ...btnBase, backgroundColor: "#059669", color: "#fff" }}>
                Any Other UPI App
              </button>
            </div>

            {/* QR Code fallback */}
            <div style={{
              border: "1px solid #e5e7eb",
              borderRadius: "10px",
              padding: "16px",
              marginBottom: "20px",
              backgroundColor: "#f9fafb",
              textAlign: "center",
            }}>
              <p style={{ fontSize: "13px", color: "#555", marginBottom: "10px" }}>
                Or scan this QR with any UPI app:
              </p>
              <QRCode
                value={`upi://pay?pa=${YOUR_UPI_ID}&pn=${encodeURIComponent(PAYEE_NAME)}&am=${AMOUNT}&cu=INR`}
                size={140}
              />
              <p style={{ fontSize: "12px", color: "#888", marginTop: "8px" }}>
                UPI ID: <strong>{YOUR_UPI_ID}</strong> &nbsp;|&nbsp; Amount: <strong>₹{AMOUNT}</strong>
              </p>
            </div>

            <hr style={{ borderColor: "#e5e7eb", margin: "16px 0" }} />

            {/* UTR Input */}
            <p style={{ fontWeight: "600", marginBottom: "4px", fontSize: "14px" }}>
              After paying, enter your UTR / Transaction ID:
            </p>
            <p style={{ fontSize: "12px", color: "#888", marginBottom: "10px" }}>
              GPay → UPI Ref. No. &nbsp;|&nbsp; PhonePe → Transaction ID &nbsp;|&nbsp; Paytm → UTR Number
              &nbsp;|&nbsp; Or check your bank SMS.
            </p>

            <input
              type="text"
              placeholder="Enter UTR / Transaction ID"
              value={utrNumber}
              onChange={(e) => setUtrNumber(e.target.value.replace(/\s/g, "").slice(0, 22))}
              style={{
                padding: "11px 14px",
                fontSize: "15px",
                width: "100%",
                boxSizing: "border-box",
                borderRadius: "8px",
                border: "1px solid #d1d5db",
                marginBottom: "12px",
                letterSpacing: "1px",
              }}
            />

            <button
              onClick={verifyAndRegister}
              disabled={verifying || utrNumber.trim().length < 10}
              style={{
                ...btnBase,
                backgroundColor: verifying || utrNumber.trim().length < 10 ? "#9ca3af" : "#16a34a",
                color: "#fff",
                cursor: verifying || utrNumber.trim().length < 10 ? "not-allowed" : "pointer",
              }}
            >
              {verifying ? "Verifying..." : "Verify & Get ID Card"}
            </button>

            <br />
            <button
              onClick={() => { setShowPayment(false); setAppOpened(false); setUtrNumber(""); }}
              style={{
                background: "none", border: "none", color: "#6b7280",
                cursor: "pointer", textDecoration: "underline", fontSize: "13px",
                display: "block", margin: "10px auto 0",
              }}
            >
              ← Back to Form
            </button>
          </div>
        )}

        {/* ── STEP 3: QR + CAMERA ── */}
        {qrData && (
          <div>
            <h3>Your QR Code</h3>
            <QRCode value={qrData.toString()} size={200} />
            <br /><br />
            <button onClick={openCamera}>Open Camera</button>
            <br /><br />
            <video ref={videoRef} width="320" height="240" style={{ border: "2px solid black" }} />
            <br /><br />
            <button onClick={capturePhoto}>Capture Photo</button>
            <canvas ref={canvasRef} style={{ display: "none" }} />
          </div>
        )}

        {/* ── STEP 4: ID CARD ── */}
        {photo && (
          <div style={{ marginTop: "30px" }}>
            <div
              ref={idCardRef}
              style={{
                border: "2px solid black",
                width: "300px",
                margin: "auto",
                padding: "15px",
                borderRadius: "10px",
              }}
            >
              <h3>College Event ID Card</h3>
              <p>Name : {formData.name}</p>
              <p>User ID : {userId}</p>
              <p>Event : {eventName}</p>
              <QRCode value={qrData.toString()} size={120} />
              <br /><br />
              <img src={photo} alt="User" width="120" />
            </div>
            <br />
            <button onClick={downloadCard}>Download ID Card</button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Register;
